  acgSignersHint: { la: 'ເລກອາກອນ ແລະ ຊື່ຜູ້ເຊັນ ທີ່ພິມຢູ່ຫົວ ແລະ ທ້າຍງົບການເງິນ (ກົດໝາຍບັນຊີ ມາດຕາ 20)', en: 'Tax ID and signer names printed on the financial statements (Accounting Law Art. 20)', cn: '财务报表抬头与签名处打印的税号和签字人（会计法第20条）' },
  acgTaxId: { la: 'ເລກປະຈຳຕົວຜູ້ເສຍອາກອນ', en: 'Tax ID (TIN)', cn: '纳税人识别号' },
