  fsEquityChanges: { la: 'ໃບລາຍງານການປ່ຽນແປງທຶນ', en: 'Statement of Changes in Equity', cn: '所有者权益变动表' },
  fsEqOpening: { la: 'ຍອດ ນ ວັນທີ', en: 'Balance at', cn: '余额于' },
  fsEqClosing: { la: 'ຍອດ ນ ວັນທີ', en: 'Balance at', cn: '余额于' },
  fsEqProfit: { la: 'ກຳໄລ (ຂາດທຶນ) ສຸດທິໃນງວດ', en: 'Profit (loss) for the period', cn: '本期净利润（亏损）' },
  fsEqIncrease: { la: 'ເພີ່ມທຶນ / ເພີ່ມຂຶ້ນອື່ນ', en: 'Capital contributed / other increases', cn: '投入资本 / 其他增加' },
  fsEqDecrease: { la: 'ປັນຜົນ / ຖອນທຶນ / ຫຼຸດລົງ', en: 'Dividends / drawings / decreases', cn: '分红 / 提款 / 减少' },
  fsEqNote: { la: 'ຍອດທ້າຍງວດ ເທົ່າກັບ ທຶນທັງໝົດ ໃນໃບສະຫຼຸບຊັບສົມບັດ. ກຳໄລປີກ່ອນໆ ທີ່ຍັງບໍ່ໂອນ ລວມຢູ່ຖັນ ກຳໄລສະສົມ', en: 'Closing balance equals total equity in the balance sheet. Undistributed profit of earlier years is included under retained earnings', cn: '期末余额等于资产负债表中的所有者权益合计。以前年度未分配利润计入留存收益栏' },
  fsNotes: { la: 'ບົດອະທິບາຍງົບການເງິນ', en: 'Notes to the Financial Statements', cn: '财务报表附注' },
  fsNoteGeneral: { la: 'ຂໍ້ມູນທົ່ວໄປ', en: 'General information', cn: '一般信息' },
  fsNoteCompany: { la: 'ຊື່ວິສາຫະກິດ', en: 'Entity', cn: '企业名称' },
  fsNoteAddress: { la: 'ທີ່ຢູ່', en: 'Address', cn: '地址' },
  fsNotePeriod: { la: 'ງວດລາຍງານ', en: 'Reporting period', cn: '报告期间' },
  fsNoteCurrency: { la: 'ສະກຸນເງິນລາຍງານ', en: 'Presentation currency', cn: '列报货币' },
  fsNoteCurrencyText: { la: 'ກີບ (LAK) — ກົດໝາຍວ່າດ້ວຍການບັນຊີ ມາດຕາ 7', en: 'Lao kip (LAK) — Accounting Law Art. 7', cn: '老挝基普 (LAK)——会计法第7条' },
  fsNoteBasis: { la: 'ພື້ນຖານການກະກຽມງົບການເງິນ', en: 'Basis of preparation', cn: '编制基础' },
  fsNoteBasisText: { la: 'ງົບການເງິນນີ້ກະກຽມຕາມ ກົດໝາຍວ່າດ້ວຍການບັນຊີ ແລະ ມາດຕະຖານລາຍງານການເງິນ ສຳລັບວິສາຫະກິດທີ່ບໍ່ແມ່ນຫົວໜ່ວຍທີ່ມີຜົນປະໂຫຍດສາທາລະນະ (ອີງຕາມ IFRS for SMEs) ຂອງ ສປປ ລາວ.', en: 'These financial statements are prepared under the Lao Accounting Law and the Lao Financial Reporting Standards for non-public-interest entities (based on IFRS for SMEs).', cn: '本财务报表按老挝《会计法》及非公众利益实体财务报告准则（以中小企业国际财务报告准则为基础）编制。' },
  fsNoteCash: { la: 'ເງິນສົດ ແລະ ເງິນຝາກທະນາຄານ', en: 'Cash and bank', cn: '现金及银行存款' },
  fsNoteReceivable: { la: 'ລູກໜີ້', en: 'Receivables', cn: '应收款' },
  fsNoteOtherCurrent: { la: 'ຊັບສິນໝູນວຽນອື່ນ', en: 'Other current assets', cn: '其他流动资产' },
  fsNoteFixedAssets: { la: 'ຊັບສົມບັດຄົງທີ່ ແລະ ຊັບສິນບໍ່ໝູນວຽນ', en: 'Fixed and non-current assets', cn: '固定资产及非流动资产' },
  fsNotePayable: { la: 'ເຈົ້າໜີ້', en: 'Payables', cn: '应付款' },
  fsNoteOtherLiabilities: { la: 'ໜີ້ສິນໝູນວຽນອື່ນ (ອາກອນ, ເງິນເດືອນຄ້າງຈ່າຍ…)', en: 'Other current liabilities (taxes, accrued salaries…)', cn: '其他流动负债（税费、应付工资等）' },
  fsNoteLongLiabilities: { la: 'ໜີ້ສິນໄລຍະຍາວ', en: 'Long-term liabilities', cn: '长期负债' },
  fsNoteRevenue: { la: 'ລາຍຮັບ', en: 'Revenue', cn: '收入' },
