  hrQrPosterHint: { la: 'ເປີດ app ຂອງບໍລິສັດ → ສະແກນ QR ນີ້ (ຕ້ອງຢູ່ໃນບໍລິສັດ)', en: 'Open the company app → scan this QR (you must be on site)', cn: '打开公司 App → 扫描此二维码（须在公司内）' },
