  hrQrRequireOnHint: { la: 'ພະນັກງານຕ້ອງສະແກນ QR ນີ້ທຸກຄັ້ງ — GPS ຢ່າງດຽວບໍ່ພໍ', en: 'Staff must scan this QR every time — GPS alone is not enough', cn: '员工每次必须扫此二维码 — 仅 GPS 不够' },
  hrQrRequireOffHint: { la: 'ປິດຢູ່ — ສະແກນດ້ວຍ GPS ໄດ້ (ສະແກນ QR ກໍ່ໄດ້)', en: 'Off — GPS check-in is allowed (the QR also works)', cn: '已关闭 — 可用 GPS 打卡（扫码亦可）' },
  hrQrRequireOn: { la: 'ເປີດການບັງຄັບສະແກນ QR ແລ້ວ', en: 'QR code is now required', cn: '已开启必须扫码' },
  hrQrRequireOff: { la: 'ປິດການບັງຄັບສະແກນ QR ແລ້ວ', en: 'QR code is no longer required', cn: '已关闭必须扫码' },
  hrQrGpsNote: { la: 'ຍັງກວດ GPS ທຸກຄັ້ງ — ຕ້ອງຢູ່ໃນໄລຍະສະແກນຂອງບໍລິສັດ', en: 'GPS is always checked — staff must be within the scan radius', cn: '始终校验 GPS — 须在打卡范围内' },
  hrQrSecretNote: { la: 'QR ມີລະຫັດລັບ — ຖ້າຮູບ QR ຮົ່ວອອກໄປ ໃຫ້ກົດສ້າງ QR ໃໝ່', en: 'The QR holds a secret code — if a photo of it leaks, generate a new one', cn: '二维码含密钥 — 如外泄请重新生成' },
  hrQrCreatedAt: { la: 'ສ້າງເມື່ອ', en: 'Created', cn: '生成于' },
  hrQrRegenerate: { la: 'ສ້າງ QR ໃໝ່', en: 'Generate new QR', cn: '重新生成' },
  hrQrRegenerateConfirm: { la: 'ສ້າງ QR ໃໝ່? QR ທີ່ພິມຕິດໄວ້ກ່ອນໜ້າຈະໃຊ້ບໍ່ໄດ້ອີກ — ຕ້ອງພິມອັນໃໝ່ໄປຕິດແທນ', en: 'Generate a new QR? Previously printed QR codes will stop working — print and post the new one', cn: '重新生成二维码？已张贴的旧二维码将失效 — 请打印新码替换' },
  hrQrRegenerated: { la: 'ສ້າງ QR ໃໝ່ແລ້ວ — ພິມໄປຕິດແທນອັນເກົ່າ', en: 'New QR generated — print it to replace the old one', cn: '已生成新二维码 — 请打印替换旧码' },
