  attHolidayNote: { la: 'ວັນພັກປະຈຳອາທິດ (ເສົາ-ອາທິດ) ຕັ້ງຢູ່ ຂໍ້ມູນບໍລິສັດ — ນີ້ສຳລັບວັນພັກທີ່ພະນັກງານທຸກຄົນພັກ: ທາງການ (ລັດຖະການກຳນົດ) ແລະ ບໍ່ເປັນທາງການ (ບໍລິສັດປະກາດເອງ ເຊັ່ນ ໄປທ່ຽວ, ພັກພິເສດ). ໃບເງິນເດືອນທີ່ເປັນຮ່າງ ໃຫ້ກົດຄິດໄລ່ໃໝ່ຫຼັງເພີ່ມ/ລຶບ', en: 'Weekly days off are set in the company profile — this list is for days everyone is off: official (government) and informal (announced by the company, e.g. trips, special days off). Recalculate draft payrolls after changes', cn: '每周休息日在公司信息中设置 — 此处为全员休息日：正式（政府规定）及非正式（公司宣布，如旅游、特别休假）。修改后请重新计算草稿工资单' },
