  lvTypeNote: { la: 'ນັບເປັນມື້ເຮັດວຽກ (ບໍ່ລວມວັນພັກປະຈຳອາທິດ ແລະ ວັນພັກ). ຂີດຈຳກັດຕໍ່ປີນັບຄຳຂໍທີ່ລໍຖ້າ + ອະນຸມັດແລ້ວ — ກວດຕອນພະນັກງານຂໍ ແລະ ຕອນອະນຸມັດ. ປະເພດທີ່ມີຄຳຂໍແລ້ວລຶບບໍ່ໄດ້, ປິດໃຊ້ງານແທນ', en: 'Counted in workdays (weekly days off and holidays excluded). The yearly limit counts pending + approved requests and is checked on request and on approval. Types with requests cannot be deleted — turn them off instead', cn: '按工作日计算（不含每周休息日与假日）。年度上限计入待审批与已批准的申请，在申请及审批时检查。已有申请的类型不能删除，请停用' },
