  lvNoTypes: { la: 'ຍັງບໍ່ມີປະເພດການລາ — ອະນຸມັດຕາມປະເພດເດີມ (ຕັ້ງປະເພດໄດ້ທີ່ ຕັ້ງຄ່າ → ປະເພດການລາພັກ)', en: 'No leave types yet — approved as requested (set them up in Settings → Leave types)', cn: '尚无请假类型 — 按原类型批准（在 设置 → 请假类型 中设置）' },
  leaveNote: { la: 'ພະນັກງານສົ່ງຄຳຂໍລາພັກຜ່ານ app ມືຖື. ອະນຸມັດ = ບັນທຶກລາພັກລົງການເຂົ້າວຽກ ແລະ ເງິນເດືອນນັບຕາມ; ເດືອນທີ່ຈ່າຍເງິນເດືອນແລ້ວ ອະນຸມັດບໍ່ໄດ້', en: 'Employees send leave requests from the mobile app. Approving records the leave in attendance and payroll follows it; months already paid cannot be approved', cn: '员工通过手机应用提交请假。批准后记入考勤并影响工资；已发薪的月份无法批准' },
  attCorrections: { la: 'ແຈ້ງລືມສະແກນ', en: 'Missed scans', cn: '漏打卡申请' },
  corrDate: { la: 'ວັນທີ', en: 'Date', cn: '日期' },
  corrApproveHint: { la: 'ບັນທຶກເວລາທີ່ຂໍລົງການເຂົ້າວຽກ — ເວລາທີ່ບໍ່ໄດ້ຂໍ ຄົງຕາມທີ່ສະແກນໄວ້, ຄິດມາຊ້າ / ອອກກ່ອນ ໃໝ່', en: 'Writes the requested times to attendance — times not requested keep the scanned value; late / early minutes are recalculated', cn: '将申请的时间记入考勤 — 未申请的时间保留打卡记录，重新计算迟到/早退' },
  corrRejectHint: { la: 'ບໍ່ບັນທຶກຫຍັງລົງການເຂົ້າວຽກ — ພະນັກງານເຫັນໝາຍເຫດໃນ app', en: 'Nothing is written to attendance — the employee sees the note in the app', cn: '不写入考勤 — 员工可在应用中看到备注' },
  corrNote: { la: 'ພະນັກງານແຈ້ງລືມສະແກນຜ່ານ app ມືຖື ພ້ອມເວລາເຂົ້າ / ອອກທີ່ລືມ (ໃນວົງເລັບ = ເວລາທີ່ສະແກນໄວ້). ອະນຸມັດ = ບັນທຶກເວລາລົງການເຂົ້າວຽກ; ເດືອນທີ່ຈ່າຍເງິນເດືອນແລ້ວ ອະນຸມັດບໍ່ໄດ້', en: 'Employees report missed scans from the mobile app with the missing check-in / check-out time (in brackets = time already scanned). Approving writes the time to attendance; months already paid cannot be approved', cn: '员工通过手机应用申报漏打卡及时间（括号内为已打卡时间）。批准后写入考勤；已发薪的月份无法批准' },

